<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
$p=0;$f=0;$ok=function(bool $v,string $n)use(&$p,&$f){echo($v?'[PASS] ':'[FAIL] ').$n.PHP_EOL;$v?$p++:$f++;};
$pdo=Database::getInstance();$pdo->exec(file_get_contents(DATABASE_PATH.'/schema.sql'));$pdo->exec('DELETE FROM quiz_answers;DELETE FROM quiz_questions;DELETE FROM quizzes;DELETE FROM question_conflicts;DELETE FROM question_sources;DELETE FROM questions;DELETE FROM subjects;DELETE FROM modules;');
$pdo->exec("INSERT INTO modules(name) VALUES ('Frequency Test Module')");$m=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO subjects(module_id,name) VALUES (?,?)")->execute([$m,'Frequency Test Subject']);$s=(int)$pdo->lastInsertId();
$base=['subject_id'=>$s,'type'=>'essay','answer_status'=>'available','answer'=>'answer','frequency'=>1];
$a=Question::createQuestion($base+['question_text'=>'Zero one','appearances'=>[]]);$ok($a['success'],'A. Zero appearances with frequency 1 is valid');
$a=Question::createQuestion($base+['question_text'=>'Zero five','frequency'=>5,'appearances'=>[]]);$ok($a['success'],'B. Zero appearances with frequency 5 is valid');
$one=$base+['question_text'=>'One appearance','appearances'=>[['source_name'=>'final','exam_year'=>2025,'exam_term'=>'first']]];$a=Question::createQuestion($one);$ok($a['success'],'C. One appearance with frequency 1 is valid');
$two=$base; $two['question_text']='Two appearances'; $two['frequency']=2; $two['appearances']=[['source_name'=>'final','exam_year'=>2025,'exam_term'=>'first'],['source_name'=>'end_module','exam_year'=>2026,'exam_term'=>'second']];$a=Question::createQuestion($two);$twoId=(int)($a['id']??0);$ok($a['success'],'D. Two appearances with frequency 2 is valid');
$bad=$two;$bad['question_text']='Two appearances frequency one';$bad['frequency']=1;$a=Question::createQuestion($bad);$ok(!$a['success']&&str_contains(implode(' ',$a['errors']),'Frequency must equal'),'E. Two appearances with frequency 1 is rejected');
$bad['question_text']='Two appearances frequency three';$bad['frequency']=3;$a=Question::createQuestion($bad);$ok(!$a['success'],'F. Two appearances with frequency 3 is rejected');
$third=$two;$third['frequency']=3;$third['appearances'][]=['source_name'=>'final','exam_year'=>2027,'exam_term'=>'first'];$a=Question::updateQuestion($twoId,$third);$ok($a['success']&&(int)Question::getQuestionById($twoId)['frequency']===3,'G. Adding an appearance synchronizes frequency to 3');
$reduced=$third;$reduced['frequency']=2;array_pop($reduced['appearances']);$a=Question::updateQuestion($twoId,$reduced);$ok($a['success']&&(int)Question::getQuestionById($twoId)['frequency']===2,'H. Removing an appearance synchronizes frequency to 2');
$empty=$reduced;$empty['frequency']=5;$empty['appearances']=[];$a=Question::updateQuestion($twoId,$empty);$ok($a['success']&&count(Question::getSources($twoId))===0&&(int)Question::getQuestionById($twoId)['frequency']===5,'I. Removing all appearances restores independent frequency');
$json=function(array $record)use($m,$s){return JsonImporter::parse(json_encode(['questions'=>[$record]],JSON_THROW_ON_ERROR),$m,$s);};
$j=$json(['type'=>'essay','question'=>'JSON no appearance one','frequency'=>1]);$ok($j['summary']['valid']===1,'J. JSON frequency 1 without appearances is valid');
$j=$json(['type'=>'essay','question'=>'JSON no appearance five','frequency'=>5]);$ok($j['summary']['valid']===1,'K. JSON frequency 5 without appearances is valid');
$j=$json(['type'=>'essay','question'=>'JSON two valid','frequency'=>2,'appearances'=>[['source'=>'final','year'=>2025,'term'=>'first'],['source'=>'end_module','year'=>2026,'term'=>'second']]]);$ok($j['summary']['valid']===1,'L. JSON two appearances with frequency 2 is valid');
$j=$json(['type'=>'essay','question'=>'JSON two invalid one','frequency'=>1,'appearances'=>[['source'=>'final','year'=>2025,'term'=>'first'],['source'=>'end_module','year'=>2026,'term'=>'second']]]);$ok($j['summary']['invalid']===1&&str_contains(implode(' ',$j['invalid'][0]['errors']),'Frequency'),'M. JSON two appearances with frequency 1 is rejected in preview');
$j=$json(['type'=>'essay','question'=>'JSON two invalid three','frequency'=>3,'appearances'=>[['source'=>'final','year'=>2025,'term'=>'first'],['source'=>'end_module','year'=>2026,'term'=>'second']]]);$ok($j['summary']['invalid']===1,'N. JSON two appearances with frequency 3 is rejected in preview');
$merge=$base; $merge['question_text']='Merge frequency question'; $merge['frequency']=2; $merge['appearances']=[['source_name'=>'final','exam_year'=>2025,'exam_term'=>'first'],['source_name'=>'end_module','exam_year'=>2026,'exam_term'=>'second']];$made=Question::createQuestion($merge);$mergeJson=$json(['type'=>'essay','question'=>'Merge frequency question','frequency'=>3,'appearances'=>[['source'=>'final','year'=>2027,'term'=>'first']]]);$import=JsonImporter::import($mergeJson['valid']);$mergeRow=Database::fetchOne('SELECT id,frequency FROM questions WHERE question_text=?',['Merge frequency question']);$ok($import['success']&&$import['added_appearances']===1&&(int)$mergeRow['frequency']===3&&count(Question::getSources((int)$mergeRow['id']))===3,'O/P. Merge validates total appearances and preserves existing rows');
$duplicateJson=$json(['type'=>'essay','question'=>'Merge frequency question','frequency'=>3,'appearances'=>[['source'=>'final','year'=>2027,'term'=>'first']]]);$duplicateImport=JsonImporter::import($duplicateJson['valid']);$ok($duplicateImport['success']&&$duplicateImport['duplicate_appearances']===1&&count(Question::getSources((int)$mergeRow['id']))===3,'O. Duplicate appearance remains ignored without data loss');
$ok(count(Question::getQuestions(['module_id'=>$m,'source_names'=>['final'],'exam_year'=>2027,'exam_term'=>'first'],100,0))===1,'Q. Existing Question Bank appearance filters remain correct');
$ok(class_exists('Quiz'),'R. Quiz generation/grading service remains available');
echo "Frequency Consistency Test Results: {$p} Passed, {$f} Failed".PHP_EOL;exit($f?1:0);
